{
  "version": 2,
  "builds": [
    {
      "src": "src/pages/api/**",
      "use”: "next" 
    },
    {
      "src": "src/pages/**/*.tsx",
      "use": "next" 
    }
  ],
  "routes": [
    {
      "src": "/api/.*",
      "methods": ["GET","POST","PUT","DELETE","PATCH","OPTIONS"],
      "destination": "/api/$1"
    },
    {
      "src": "/((?!api).*)",
      "methods": ["GET","HEAD"],
      "destination": "/$1"
    }
  ],
  "env": {
    "NEXT_PUBLIC_APP_NAME": "TodoElephant",
    "DISABLE_TELEMETRY": "true"
  },
  "headers": [
    {
      "source": "/(?!/api)",
      "headers": [
        {"key": "X-Content-Type-Options", "value": "nosniff"},
        {"key": "X-Frame-Options", "value": "DENY"},
        {"key": "X-XSS-Protection", "value": "1; mode=block"},
        {"key": "Referrer-Policy", "value": "strict-origin-when-cross-origin"},
        {"key": "Content-Security-Policy", "value": "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval'; style-src 'self' 'unsafe-inline'; image-src 'self' data:; font-src 'self' data:; connect-src 'self' https:; frame-ancestors 'none'"}
      ]
    }
  ],
  "routes": [
    {
      "src": "/(.*)",
      "dest": "/index.html"
    }
  ]
}

NEXT_PUBLIC_APP_NAME=TodoElephant
NEXT_PUBLIC_API_URL=https://api.todo-elephant.app
JWT_SECRET=${{ secrets.JWT_SECRET }}
ETSY_API_KEY=${{ secrets.ETSY_API_KEY }}
ETSY_APP_KEY=${{ secrets.ETSY_APP_KEY }}
AMAZON_API_KEY=${{ secrets.AMAZON_API_KEY }}
AMAZON_ACCESS_TOKEN=${{ secrets.AMAZON_ACCESS_TOKEN }}
MONGODB_URI=mongodb+srv://<user>:<password>@cluster0.mongodb.net/todo-elephant?retryWrites=true&w=majority
NODE_ENV=production

// Jest configuration for end‑to‑end and unit testing
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  testMatch: ['**/tests/**/*.(ts|tsx)', '**/?(*.)+(spec|test).ts?(x)'], 
  setupFilesAfterEnv: ['<rootDir>/tests/setup.ts'],
  globals: {
    'ts-jest': {
      tsconfig: 'tsconfig.json',
    },
  },
  collectCoverageFrom: ['src/**/*.{ts,tsx}', '!src/**/__tests__/', '!src/**/index.ts'], 
  coverageDirectory: '<rootDir>/coverage',
  coverageReporters: ['text', 'lcov'], 
  verbose: true,
  moduleDirectories: ['node_modules', '<rootDir'], 
  transform: {
    '^.+\\.tsx?$': 'ts-jest',
  },
};
